question.sql:
SELECT (movies.year / 10) * 10 as decade FROM imdb.movies 
  join imdb.ratings on movies.movieid = ratings.movieid 
  group by decade order by AVG(cast(ratings.rank as float)) limit 1;

select md.directorid from imdb.movies2directors as md 
  join imdb.runningtimes as r on md.movieid = r.movieid 
  where r.time1 > 160 group by md.directorid order by count(*) desc limit 1;

select h.cell_id from scenicornot.hexgrid10km as h 
join scenicornot.locations as l on ST_Contains(h.geom, l.geom_bng) 
group by h.cell_id having count(*) >= 3 order by avg(l.average) desc limit 1;

select sum(st_distance(geom2, geom)) as distance 
  from (select geom, lag(geom) over(order by datetime) as geom2 
  from trajectory.tracking where userid ='p3')
